CREATE TABLE kups_documents(id TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES kups_groups(id),date TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('income','expense')),category TEXT NOT NULL,description TEXT NOT NULL,total_amount INTEGER NOT NULL CHECK(total_amount>0 AND total_amount<=1000000000000),counterparty TEXT NOT NULL,quantity REAL,unit TEXT NOT NULL DEFAULT '',unit_price INTEGER,product TEXT NOT NULL DEFAULT '',activity TEXT NOT NULL DEFAULT '',object_id TEXT NOT NULL DEFAULT '',source_ref TEXT NOT NULL DEFAULT '',evidence_id TEXT NOT NULL DEFAULT '',request_hash TEXT NOT NULL DEFAULT '',created_by TEXT NOT NULL,updated_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at TEXT);
ALTER TABLE kups_transactions ADD COLUMN account TEXT NOT NULL DEFAULT 'unassigned' CHECK(account IN ('cash','bank','unassigned'));
ALTER TABLE kups_transactions ADD COLUMN counterparty TEXT NOT NULL DEFAULT '';
ALTER TABLE kups_transactions ADD COLUMN document_id TEXT REFERENCES kups_documents(id);
ALTER TABLE kups_transactions ADD COLUMN product TEXT NOT NULL DEFAULT '';
ALTER TABLE kups_transactions ADD COLUMN activity TEXT NOT NULL DEFAULT '';
CREATE INDEX kups_documents_group_date ON kups_documents(group_id,date);
CREATE INDEX kups_payment_document ON kups_transactions(document_id);
CREATE TABLE kups_account_openings(group_id TEXT NOT NULL REFERENCES kups_groups(id),account TEXT NOT NULL CHECK(account IN ('cash','bank')),amount REAL NOT NULL CHECK(amount>=0),PRIMARY KEY(group_id,account));
CREATE TABLE kups_transfers(id TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES kups_groups(id),date TEXT NOT NULL,from_account TEXT NOT NULL CHECK(from_account IN ('cash','bank')),to_account TEXT NOT NULL CHECK(to_account IN ('cash','bank')),amount INTEGER NOT NULL CHECK(amount>0 AND amount<=1000000000000),description TEXT NOT NULL,evidence_id TEXT NOT NULL DEFAULT '',source_ref TEXT NOT NULL DEFAULT '',created_by TEXT NOT NULL,updated_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at TEXT,CHECK(from_account!=to_account));
CREATE INDEX kups_transfers_group_date ON kups_transfers(group_id,date);
CREATE TRIGGER kups_document_insert_lock BEFORE INSERT ON kups_documents WHEN NEW.date<(SELECT start_date FROM kups_groups WHERE id=NEW.group_id) OR substr(NEW.date,1,7)<=COALESCE((SELECT closed_through FROM kups_groups WHERE id=NEW.group_id),'') BEGIN SELECT RAISE(ABORT,'KUPS_PERIOD_LOCKED'); END;
CREATE TRIGGER kups_document_update_lock BEFORE UPDATE ON kups_documents WHEN NEW.group_id!=OLD.group_id OR NEW.kind!=OLD.kind OR NEW.date<(SELECT start_date FROM kups_groups WHERE id=NEW.group_id) OR substr(NEW.date,1,7)<=COALESCE((SELECT closed_through FROM kups_groups WHERE id=NEW.group_id),'') OR substr(OLD.date,1,7)<=COALESCE((SELECT closed_through FROM kups_groups WHERE id=OLD.group_id),'') BEGIN SELECT RAISE(ABORT,'KUPS_PERIOD_LOCKED'); END;
CREATE TRIGGER kups_document_paid_guard BEFORE UPDATE ON kups_documents WHEN EXISTS(SELECT 1 FROM kups_transactions WHERE document_id=OLD.id AND deleted_at IS NULL AND date<NEW.date) OR NEW.total_amount<(SELECT COALESCE(SUM(amount),0) FROM kups_transactions WHERE document_id=OLD.id AND deleted_at IS NULL) OR (NEW.deleted_at IS NOT NULL AND EXISTS(SELECT 1 FROM kups_transactions WHERE document_id=OLD.id AND deleted_at IS NULL)) BEGIN SELECT RAISE(ABORT,'KUPS_DOCUMENT_HAS_PAYMENTS'); END;
CREATE TRIGGER kups_payment_insert_guard BEFORE INSERT ON kups_transactions WHEN NEW.document_id IS NOT NULL AND (NOT EXISTS(SELECT 1 FROM kups_documents d WHERE d.id=NEW.document_id AND d.group_id=NEW.group_id AND d.kind=NEW.kind AND d.deleted_at IS NULL AND d.date<=NEW.date) OR NEW.amount+(SELECT COALESCE(SUM(amount),0) FROM kups_transactions WHERE document_id=NEW.document_id AND deleted_at IS NULL)>(SELECT total_amount FROM kups_documents WHERE id=NEW.document_id)) BEGIN SELECT RAISE(ABORT,'KUPS_OVERPAYMENT'); END;
CREATE TRIGGER kups_payment_update_guard BEFORE UPDATE ON kups_transactions WHEN OLD.document_id IS NOT NULL AND (NEW.document_id IS NOT OLD.document_id OR (NEW.deleted_at IS NULL AND (NOT EXISTS(SELECT 1 FROM kups_documents d WHERE d.id=NEW.document_id AND d.group_id=NEW.group_id AND d.kind=NEW.kind AND d.deleted_at IS NULL AND d.date<=NEW.date) OR NEW.amount+(SELECT COALESCE(SUM(amount),0) FROM kups_transactions WHERE document_id=NEW.document_id AND deleted_at IS NULL AND id!=OLD.id)>(SELECT total_amount FROM kups_documents WHERE id=NEW.document_id)))) BEGIN SELECT RAISE(ABORT,'KUPS_OVERPAYMENT'); END;
CREATE TRIGGER kups_transfer_insert_lock BEFORE INSERT ON kups_transfers WHEN NEW.date<(SELECT start_date FROM kups_groups WHERE id=NEW.group_id) OR substr(NEW.date,1,7)<=COALESCE((SELECT closed_through FROM kups_groups WHERE id=NEW.group_id),'') BEGIN SELECT RAISE(ABORT,'KUPS_PERIOD_LOCKED'); END;
CREATE TRIGGER kups_transfer_update_lock BEFORE UPDATE ON kups_transfers WHEN NEW.group_id!=OLD.group_id OR NEW.date<(SELECT start_date FROM kups_groups WHERE id=NEW.group_id) OR substr(NEW.date,1,7)<=COALESCE((SELECT closed_through FROM kups_groups WHERE id=NEW.group_id),'') OR substr(OLD.date,1,7)<=COALESCE((SELECT closed_through FROM kups_groups WHERE id=OLD.group_id),'') BEGIN SELECT RAISE(ABORT,'KUPS_PERIOD_LOCKED'); END;
